#include <iostream>
using namespace std;

int main() {
    int A, L, N;
    cin >> A >> L;
    cin >> N;

    int bestId = -1;
    long long bestArea = -1;

    for (int i = 1; i <= N; ++i) {
        int X, Y;
        cin >> X >> Y;

        bool fits = (A <= X && L <= Y) || (A <= Y && L <= X);

        if (fits) {
            long long area = 1LL * X * Y;
            if (bestId == -1 || area < bestArea || (area == bestArea && i < bestId)) {
                bestArea = area;
                bestId = i;
            }
        }
    }

    cout << bestId << '\n';
    return 0;
}
